def md_role(role):
    lines=[f"# راهنمای {role['name']}", '', 'نسخهٔ ۲٫۲ ایده‌آل ماکو | آموزش کاربر غیرمتخصص | ۲۶ اکتبر ۲۰۲۶', '', role['purpose'], '', '## پیش از شروع', '', COMMON_STAFF if role['id']!='customer' else 'برای ورود پیامکی باید به شمارهٔ همراه خود دسترسی داشته باشید. کلید سرویس یا حساب مدیر لازم ندارید. رمز یک‌بارمصرف فقط برای ورود خود شماست. اگر قبلاً حساب ایمیلی دارید، بدون تأیید هویت نباید فرض کنید شمارهٔ جدید به همان حساب متصل می‌شود.', '', '## صفحه‌های موردنیاز', '', '| صفحه | مسیر |', '| --- | --- |']
    for label,path in role['menus']: lines.append(f'| {label} | `/fa/{path}/` |')
    lines+=['', 'مسیرهای جدول نسبت به دامنهٔ نصب شما هستند. برای زبان دیگر، بخش fa تغییر می‌کند. فقط صفحه‌ها و دکمه‌های مجاز حساب فعلی قابل استفاده‌اند.', '', f"![پیشخوان واقعی نقش {role['name']}](../../public/manuals/assets/{role['id']}-overview.png)", '', 'شکل ۱ ـ پیشخوان همین نسخه با حساب آموزشی. اعداد این تصویر، آمار کسب‌وکار واقعی نیستند.', '', '## گردش اصلی کار', '', f"### {role['scenario']}", '']
    for number,step in enumerate(role['steps'],1): lines.extend([f'{number}. {step}', ''])
    lines += [f"![محیط کار واقعی نقش {role['name']}](../../public/manuals/assets/{role['id']}-workspace.png)", '', 'شکل ۲ ـ بخش اصلی کار این نقش. نام حساب‌ها آموزشی است؛ اطلاعات مشتری یا رمز در تصویر درج نشده است.', '']
    for title,body in role['extras']: lines+=['## '+title,'',body,'']
    if role['id']!='customer':
        lines+=['## ذخیره و وضعیت کار','',COMMON_SAVE,'','## اعلان و پیگیری','',COMMON_NOTIFICATIONS,'','## گزارش و مصرف سرویس','',COMMON_ANALYTICS,'','## دستیار اختیاری هوش مصنوعی','','دکمهٔ «کمک اختیاری هوش مصنوعی» در نوار بالای پنل است و فقط موضوع‌های مجاز نقش را نشان می‌دهد. موضوع و زبان مجاز را انتخاب کنید، درخواست روشن بنویسید و گزینهٔ رضایت ارسال متن و پرونده‌های انتخابی به ارائه‌دهنده را بخوانید و علامت بزنید؛ سپس «دریافت پیشنهاد» را بزنید. بدون تنظیم کلید/مدل سرویس توسط مالک، تولید غیرفعال است. برای محتوا، SEO، محصول یا راهنمای کار، متن مرجع را خودتان در درخواست بنویسید؛ صرف بازبودن یک صفحه باعث خواندن خودکار آن نمی‌شود. در موضوع مشتری، حداکثر پنج پروندهٔ مجاز را صریح انتخاب کنید تا سرور فقط همان دادهٔ مجاز را بخواند. موضوع تحلیل، آمار ۳۰ روز اخیر زبان انتخاب‌شده را اضافه می‌کند و به فیلتر فعلی جدول وابسته نیست. تولید، با فرمان شما مصرف ایجاد می‌کند. خروجی را بازخوانی کنید؛ پیشنهاد خودکار ذخیره، منتشر، تأیید یا برای مشتری ارسال نمی‌شود. توقف درخواست ممکن است مصرفی را که قبلاً نزد ارائه‌دهنده انجام شده برنگرداند.','','نمونهٔ درخواست مناسب:','',role['ai'],'']
    else: lines+=['## دستیار عمومی اختیاری','',role['ai'],'']
    lines+=['## خطاهای رایج و اقدام درست','','| نشانه | اقدام |','| --- | --- |']
    for symptom,action in ERRORS:lines.append(f'| {symptom} | {action} |')
    lines+=['','## تمرین پایان آموزش','',f"۱. مسیر «{role['scenario']}» را با دادهٔ آموزشی و بدون ارسال ناخواسته به افراد واقعی مرور کنید.",'','۲. نشان دهید نتیجهٔ کار کجا روی سرور ثبت می‌شود و چه تفاوتی با متن ذخیره‌نشده در مرورگر دارد.','','۳. یک خطای دسترسی یا وضعیت انتظار را توضیح دهید و مسیر ارجاع درست را انتخاب کنید.','','۴. گزارش یا صفحهٔ نتیجه را دوباره باز کنید و مطمئن شوید اطلاعات درست، زبان درست و وضعیت درست دیده می‌شود.','','## تحویل کار به نقش بعدی','',role['handoff'],'','## حدود اختیار','',role['limits'],'','## چک‌لیست پایان روز','','- کارهای ذخیره‌نشده را تعیین تکلیف کنید و پاسخ موفق سرور را ببینید.','- درخواست یا وظیفهٔ باز را بدون مسئول و اقدام بعدی رها نکنید.','- پیام خطا یا ارسال ناموفق را با اطلاعات لازم و بدون رمز/کلید گزارش کنید.','- روی دستگاه مشترک از حساب خارج شوید.','- برای کار بعدی از راهنمای همان نقش و بخش کمک بگیرید.','','## راهنماهای مرتبط','','- [سند تفصیلی توسعه](../EXPANSION-SPEC-2.2.fa.md)','- [برنامهٔ اجرا](../IMPLEMENTATION-PLAN-2.2.fa.md)','- [شروع نصب و استفاده](../START-HERE-2.2.0.fa.md)','- [سرویس‌ها و DNS و SEO](../INSTALL-SERVICES-SEO-2.2.fa.md)','- [گزارش آزمون این نسخه](../VERIFICATION-2.2.0.fa.md)','']
    return '\n'.join(lines)

def inline(text):
    safe=html.escape(text)
    safe=re.sub(r'`([^`]+)`',r'<bdi><code>\1</code></bdi>',safe)
    safe=re.sub(r'\[([^\]]+)\]\(([^)]+)\)',lambda m:'<a href="'+html.escape(m.group(2),quote=True)+'">'+m.group(1)+'</a>',safe)
    return safe

def html_body(markdown,role):
    out=[];table=False;listing=None
    def close():
        nonlocal table,listing
        if table:out.append('</tbody></table>');table=False
        if listing:out.append('</'+listing+'>');listing=None
    lines=markdown.splitlines();i=0
    while i<len(lines):
        line=lines[i];i+=1
        if not line.strip():close();continue
        if line.startswith('|'):
            cells=[c.strip() for c in line.strip('|').split('|')]
            if all(re.fullmatch(r'[: -]+',c) for c in cells):continue
            if not table:close();out.append('<table><thead><tr>'+''.join('<th>'+inline(c)+'</th>' for c in cells)+'</tr></thead><tbody>');table=True
            else:out.append('<tr>'+''.join('<td>'+inline(c)+'</td>' for c in cells)+'</tr>')
            continue
        m=re.fullmatch(r'!\[([^]]+)\]\(([^)]+)\)',line)
        if m:
            close();src='assets/'+Path(m.group(2)).name;out.append('<figure><img loading="lazy" src="'+src+'" alt="'+html.escape(m.group(1),quote=True)+'"></figure>');continue
        if line.startswith('#'):
            close();level=len(line)-len(line.lstrip('#'));out.append(f'<h{level}>'+inline(line[level:].strip())+f'</h{level}>');continue
        match=re.match(r'^(\d+)\. (.+)',line)
        if match:
            if listing!='ol':close();out.append('<ol start="'+str(int(match.group(1)))+'">');listing='ol'
            out.append('<li>'+inline(match.group(2))+'</li>');continue
        if line.startswith('- '):
            if listing!='ul':close();out.append('<ul>');listing='ul'
            out.append('<li>'+inline(line[2:])+'</li>');continue
        close();out.append('<p>'+inline(line)+'</p>')
    close();return '\n'.join(out)

def main():
    DOCS.mkdir(parents=True,exist_ok=True);PUBLIC.mkdir(parents=True,exist_ok=True)
    style='''@font-face{font-family:Vazirmatn;src:url('../fonts/Vazirmatn.woff2') format('woff2');font-display:swap}*{box-sizing:border-box}body{margin:0;background:#f3f6f9;color:#18232f;font:16px/1.95 Vazirmatn,"DejaVu Sans",sans-serif}main{max-width:1040px;margin:30px auto;background:white;padding:50px 60px;border-radius:16px}h1{font-size:30px;line-height:1.6;margin:20px 0}h2{font-size:23px;margin:42px 0 15px}h3{font-size:19px}a{color:#075c87;text-decoration-thickness:1px;text-underline-offset:4px}nav{display:flex;gap:25px;flex-wrap:wrap;border-bottom:1px solid #dce5ec;padding-bottom:20px}p{margin:14px 0}ol,ul{padding-inline-start:28px}li{padding:6px 0}table{width:100%;border-collapse:collapse;margin:22px 0;font-size:14px}th,td{border:1px solid #d5e0e8;padding:12px;vertical-align:top;text-align:right}th{background:#e8f0f5}tr:nth-child(even){background:#f8fafc}code{font-family:monospace;direction:ltr;overflow-wrap:anywhere}figure{margin:28px 0}img{max-width:100%;height:auto;border:1px solid #dce5ec;border-radius:8px}footer{margin-top:40px;color:#586975}.index-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.index-grid a{display:block;padding:16px;border:1px solid #dce5ec;border-radius:8px}@media(max-width:700px){main{margin:0;padding:24px 20px;border-radius:0}.index-grid{grid-template-columns:1fr}h1{font-size:25px}table{font-size:12px}th,td{padding:7px}}@media print{body{background:white;font-size:11pt}main{margin:0;padding:0;max-width:none}nav{display:none}h1,h2,h3{break-after:avoid}figure,tr{break-inside:avoid}a{color:inherit}}
'''
    (PUBLIC/'style.css').write_text(style,encoding='utf8')
    for role in ROLES:
        markdown=md_role(role);(DOCS/(role['id']+'.fa.md')).write_text(markdown,encoding='utf8')
        body=html_body(markdown,role)
        # Technical documents remain downloadable with the source package; all
        # in-site manual links resolve to real role pages, never local file paths.
        body=re.sub(r'<h2>راهنماهای مرتبط</h2>.*','',body,flags=re.S)
        document='<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex,follow"><title>راهنمای '+html.escape(role['name'])+' | ایده‌آل ماکو</title><link rel="stylesheet" href="style.css"></head><body><main><nav><a href="index.html">فهرست راهنماهای نقش‌ها</a><a href="/fa/">بازگشت به سایت</a></nav>'+body+'<footer>راهنمای نسخهٔ ۲٫۲ ایده‌آل ماکو</footer></main></body></html>'
        (PUBLIC/(role['id']+'.html')).write_text(document,encoding='utf8')
    cards=''.join('<a href="'+r['id']+'.html">'+html.escape(r['name'])+'</a>' for r in ROLES)
    (PUBLIC/'index.html').write_text('<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex,follow"><title>آموزش نقش‌ها در ایده‌آل ماکو</title><link rel="stylesheet" href="style.css"></head><body><main><h1>آموزش نقش‌ها در ایده‌آل ماکو</h1><p>راهنمای نقش خود را انتخاب کنید. هر راهنما ورود، صفحه‌های مجاز، یک گردش کامل کار، خطاهای رایج و نحوهٔ تحویل کار را توضیح می‌دهد.</p><div class="index-grid">'+cards+'</div><p>تصاویر از اجرای نسخهٔ production با حساب‌های آموزشی تهیه شده‌اند.</p></main></body></html>',encoding='utf8')
    (DOCS/'README.fa.md').write_text('# راهنماهای مستقل نقش‌ها\n\n'+'\n'.join('- ['+r['name']+']('+r['id']+'.fa.md)' for r in ROLES)+'\n\nنسخهٔ تصویری HTML در پوشهٔ public/manuals قرار دارد و روی سایت از /manuals/index.html باز می‌شود.\n',encoding='utf8')
    print('Generated 12 Persian role guides, 13 HTML pages and shared styles.')

if __name__=='__main__':main()
